"""Explicit causal mask admits maintained KV repetition and efficient SDPA.

Torch 2.12.1 uses CUTLASS OpMultiplyAddFastF32 for float/SM80 attention.
FP32 tensors and process IEEE GEMM settings do not make this arithmetic IEEE.
https://github.com/pytorch/pytorch/blob/v2.12.1/aten/src/ATen/native/transformers/cuda/mem_eff_attention/gemm_kernel_utils.h
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import cast

import torch
from torch import nn
from torch.nn.attention import SDPBackend, sdpa_kernel
from transformers.modeling_outputs import BaseModelOutputWithPast
from transformers.models.qwen3.modeling_qwen3 import Qwen3Model

from benchmarks.analysis.cuda.scorer import FP32Scorer, require_fp32
from wyat.backends.kai.encoding import EncodedRequest
from wyat.backends.kai.torch import CandidateHead, KaiScorer
from wyat.core import Request


class MaskedBackbone(nn.Module):
    """One existing backbone owner; fresh square full-prefill mask per call.

    The original model/config is unchanged. No cache, registry mutation or
    backend fallback is permitted. HF performs the KV repetition itself.
    """

    def __init__(self, model: Qwen3Model) -> None:
        super().__init__()
        if (
            any(module.training for module in model.modules())
            or model.has_sliding_layers
            or model.config._attn_implementation != "sdpa"
        ):
            raise ValueError("Efficient candidate requires eval full attention")
        self.model = model
        self.training = False

    def forward(
        self, *, input_ids: torch.Tensor, use_cache: bool
    ) -> BaseModelOutputWithPast:
        if (
            use_cache is not False
            or input_ids.ndim != 2
            or input_ids.dtype != torch.long
        ):
            raise ValueError("Efficient candidate requires uncached 2D token IDs")
        length = input_ids.shape[1]
        if length == 0:
            raise ValueError("Efficient candidate requires nonempty token IDs")
        positions = torch.arange(length, device=input_ids.device)
        mask = (positions[:, None] >= positions[None, :])[None, None]
        # This nested context deliberately overrides FP32Scorer's math control.
        with sdpa_kernel(SDPBackend.EFFICIENT_ATTENTION):
            return cast(
                BaseModelOutputWithPast,
                self.model(input_ids=input_ids, attention_mask=mask, use_cache=False),
            )


@dataclass(frozen=True)
class ScorerView:
    """Only the fields consumed by the immutable FP32Scorer boundary."""

    base: KaiScorer
    backbone: MaskedBackbone

    @property
    def head(self) -> CandidateHead:
        return self.base.head

    @property
    def device(self) -> torch.device:
        return self.base.device

    @property
    def pad_id(self) -> int:
        return self.base.pad_id

    def encode_request(self, request: Request) -> EncodedRequest:
        return self.base.encode_request(request)


def efficient_scorer(base: KaiScorer) -> FP32Scorer:
    require_fp32(base)
    view = ScorerView(base, MaskedBackbone(base.backbone))
    # The frozen research API names KaiScorer nominally but consumes only this
    # typed view's encoder/device/pad/head/module-call contract. Do not change
    # its old source or misrepresent the adapter as a Qwen3Model subclass.
    return FP32Scorer(cast(KaiScorer, view))

"""Diagnostic dispatch metadata only; never attach to ordinary inference."""

from __future__ import annotations

import warnings
from collections.abc import Sequence
from typing import Protocol, cast

import torch
from torch._C._autograd import DeviceType
from torch.profiler import ProfilerActivity, profile
from torch.utils._python_dispatch import TorchDispatchMode

from benchmarks.analysis.cuda.manifest import MODEL_ID
from wyat import Model
from wyat.benchmark import BenchmarkCycle, BenchmarkEngine, _run
from wyat.core import Scorer
from wyat.evaluation import EvaluationCase


class Operator(Protocol):
    def __call__(self, *args: object, **kwargs: object) -> object: ...


def tensor_metadata(value: torch.Tensor) -> dict[str, object]:
    return {
        "shape": list(value.shape),
        "stride": list(value.stride()),
        "dtype": str(value.dtype),
        "device": str(value.device),
    }


# Upstream TorchDispatchMode.__init_subclass__ lacks annotations.
class Dispatch(TorchDispatchMode):  # type: ignore[no-untyped-call]
    """Keep primitives only; do not extend any attention tensor lifetime."""

    def __init__(self) -> None:
        super().__init__()  # type: ignore[no-untyped-call]  # upstream initializer
        self.events: list[dict[str, object]] = []

    def __torch_dispatch__(
        self,
        func: object,
        types: tuple[type[object], ...],
        args: tuple[object, ...] = (),
        kwargs: dict[str, object] | None = None,
    ) -> object:
        name = str(func)
        if "scaled_dot_product" in name:
            tensors = [arg for arg in args[:4] if isinstance(arg, torch.Tensor)]
            event: dict[str, object] = {
                "operator": name,
                "tensors": [tensor_metadata(value) for value in tensors],
            }
            if "efficient_attention" in name and len(tensors) == 4:
                params = torch.backends.cuda.SDPAParams(
                    tensors[0], tensors[1], tensors[2], tensors[3], 0.0, False, False
                )
                event["efficient_eligible"] = (
                    torch.backends.cuda.can_use_efficient_attention(params, debug=True)
                )
            self.events.append(event)
        # Operator overloads are an untyped upstream variadic callable boundary.
        return cast(Operator, func)(*args, **({} if kwargs is None else kwargs))


def profile_batch(
    scorer: Scorer,
    cases: tuple[EvaluationCase, ...],
    *,
    name: str,
) -> tuple[BenchmarkCycle, dict[str, object]]:
    observer = Dispatch()
    with (
        warnings.catch_warnings(record=True) as caught,
        profile(
            activities=[ProfilerActivity.CPU, ProfilerActivity.CUDA], record_shapes=True
        ) as profiler,
        observer,
    ):
        cycle = _run(
            BenchmarkEngine(
                name, Model(scorer, model_id=MODEL_ID), batch_size=len(cases)
            ),
            cases,
        )
        torch.cuda.synchronize()
    events = profiler.key_averages(group_by_input_shape=True)
    kernels = [
        {
            "name": event.name,
            "duration_us": event.time_range.elapsed_us(),
            "device_index": event.device_index,
        }
        for event in profiler.events()
        if event.device_type == DeviceType.CUDA
    ]
    return cycle, {
        "case_ids": [case.id for case in cases],
        "dispatch": observer.events,
        "operators": [
            {
                "name": event.key,
                "count": event.count,
                "shapes": event.input_shapes,
                "self_cpu_time_us": event.self_cpu_time_total,
                "self_device_time_us": event.self_device_time_total,
            }
            for event in events
        ],
        "warnings": [str(item.message) for item in caught],
        "cuda_kernel_events": kernels,
        "cuda_kernel_names_available": bool(kernels),
        "timing_scope": "Intrusive profiler/dispatch diagnostics; no speed claim",
    }


def efficient_dispatch_gate(
    events: Sequence[dict[str, object]], *, batch_size: int, length: int
) -> bool:
    if len(events) != 28:
        return False
    expected = [batch_size, 16, length, 128]
    for event in events:
        if (
            event["operator"] != "aten._scaled_dot_product_efficient_attention.default"
            or event.get("efficient_eligible") is not True
        ):
            return False
        tensors = cast(list[dict[str, object]], event["tensors"])
        if len(tensors) != 4:
            return False
        if any(
            value["shape"] != expected
            or value["dtype"] != "torch.float32"
            or cast(list[int], value["stride"])[-1] != 1
            or value["device"] != "cuda:0"
            for value in tensors[:3]
        ):
            return False
        # Torch converts the boolean causal mask to a padded floating-point bias.
        if (
            tensors[3]["shape"] != [batch_size, 16, length, length]
            or tensors[3]["dtype"] != "torch.float32"
        ):
            return False
    return True

